<?php
function rzz_has_seo(){return defined('WPSEO_VERSION')||defined('RANK_MATH_VERSION')||defined('AIOSEO_VERSION')||defined('SEOPRESS_VERSION');}
add_filter('pre_get_document_title',function($title){if(rzz_has_seo())return $title;if(is_singular()&&rzz_meta('meta_title'))return rzz_meta('meta_title');if(is_front_page())return 'RZZ LAW | Legal Advice & Representation in Kosovo';return $title;});
add_action('wp_head',function(){if(rzz_has_seo()||is_search()||is_404())return;
$description=is_front_page()?rzz_setting('hero_text','Legal advice and representation for businesses, institutions and individuals in Kosovo.'):'';
if(is_singular())$description=rzz_meta('meta_description')?:($description?:wp_strip_all_tags(get_the_excerpt()));if(is_post_type_archive('expertise'))$description='Explore RZZ LAW’s eight practice areas for businesses, institutions and individuals in Kosovo.';if(is_post_type_archive('team'))$description='Meet the lawyers at RZZ LAW. View their biographies, practice areas and contact details.';if(is_home())$description='Legal perspectives, analysis and updates from RZZ LAW.';
$url=is_singular()?get_permalink():(is_front_page()?home_url('/'):get_post_type_archive_link(get_query_var('post_type')));if(is_home())$url=get_permalink(get_option('page_for_posts'));if(!$url||get_query_var('paged')>1)$url=get_pagenum_link();$title=wp_get_document_title();
echo '<meta name="description" content="'.esc_attr(wp_trim_words($description,35,'')).'">';if(!is_singular())echo '<link rel="canonical" href="'.esc_url($url).'">';
echo '<meta property="og:type" content="'.(is_singular('post')?'article':'website').'"><meta property="og:site_name" content="RZZ LAW"><meta property="og:title" content="'.esc_attr($title).'"><meta property="og:description" content="'.esc_attr($description).'"><meta property="og:url" content="'.esc_url($url).'"><meta name="twitter:card" content="summary_large_image">';
$image=rzz_banner_image()?:((is_singular()&&has_post_thumbnail())?get_the_post_thumbnail_url(null,'large'):rzz_setting('hero_image',rzz_asset('images/hero1-1600.webp')));if($image)echo '<meta property="og:image" content="'.esc_url($image).'"><meta property="og:image:alt" content="'.esc_attr(rzz_current_image_details()['alt']).'">';
$schema=['@type'=>'LegalService','@id'=>home_url('/#firm'),'name'=>'RZZ LAW','url'=>home_url('/'),'areaServed'=>['@type'=>'Country','name'=>'Kosovo']];foreach(['address','phone'=>'telephone','email'] as $key=>$value){$setting=is_int($key)?$value:$key;if(rzz_setting($setting))$schema[$value]=rzz_setting($setting);}if(rzz_setting('linkedin'))$schema['sameAs']=[rzz_setting('linkedin')];if(rzz_setting('availability','Monday to Friday, 08:00 - 16:00')==='Monday to Friday, 08:00 - 16:00')$schema['openingHoursSpecification']=[['@type'=>'OpeningHoursSpecification','dayOfWeek'=>['Monday','Tuesday','Wednesday','Thursday','Friday'],'opens'=>'08:00','closes'=>'16:00']];$graph=[$schema];if($image){$photo=rzz_current_image_details();$graph[]=['@type'=>'ImageObject','@id'=>$image.'#image','contentUrl'=>$image,'name'=>$photo['title'],'caption'=>$photo['alt'],'description'=>$photo['description']];}
if(is_singular('expertise'))$graph[]=['@type'=>'Service','name'=>get_the_title(),'description'=>$description,'url'=>$url,'provider'=>['@id'=>home_url('/#firm')]];
if(is_singular('team')){$person=['@type'=>'Person','name'=>get_the_title(),'url'=>$url,'worksFor'=>['@id'=>home_url('/#firm')]];if(rzz_meta('role'))$person['jobTitle']=rzz_meta('role');$graph[]=$person;}
if(is_singular('post'))$graph[]=['@type'=>'Article','headline'=>get_the_title(),'datePublished'=>get_the_date(DATE_W3C),'dateModified'=>get_the_modified_date(DATE_W3C),'author'=>['@type'=>rzz_meta('author_name')==='RZZ LAW'?'Organization':'Person','name'=>rzz_meta('author_name')?:get_the_author_meta('display_name',get_post_field('post_author',get_the_ID()))],'mainEntityOfPage'=>$url];
if(!is_front_page()){$items=[['@type'=>'ListItem','position'=>1,'name'=>'Home','item'=>home_url('/')]];if(is_singular(['expertise','team']))$items[]=['@type'=>'ListItem','position'=>2,'name'=>ucfirst(get_post_type()),'item'=>get_post_type_archive_link(get_post_type())];$items[]=['@type'=>'ListItem','position'=>count($items)+1,'name'=>$title,'item'=>$url];$graph[]=['@type'=>'BreadcrumbList','itemListElement'=>$items];}
echo '<script type="application/ld+json">'.wp_json_encode(['@context'=>'https://schema.org','@graph'=>$graph],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT).'</script>';
},5);
add_filter('wp_robots',function($robots){if(is_search())$robots['noindex']=true;return $robots;});
